    decimal_string, places = data
    if places == 0:
        return str(int(decimal_string))
    sign = '-' if decimal_string.startswith('-') else ''
    if sign:
        decimal_string = decimal_string[1:]
    if decimal_string == '0':
        return '0.' + '0' * places
    integer_part, fractional_part = decimal_string.split('.')
    if len(fractional_part) <= places:
        fractional_part = fractional_part + '0' * (places - len(fractional_part))
    else:
        fractional_part = fractional_part[:places]
        next_digit = fractional_part[places]
        current_sum = int(fractional_part)
        if next_digit == '5':
            if len(fractional_part) > places:
                current_sum += 1
            if current_sum % 2 == 0:
                pass
            else:
                current_sum -= 1
        else:
            pass
    result = integer_part + '.' + str(current_sum).zfill(places)
    if sign and result != '0.' + '0' * places:
